def oracle(inp: bytes) -> bytes:
    return AES.new(key, AES.MODE_ECB).encrypt(pad(inp+secret,16))
def recover():
    known=b''
    for i in range(len(secret)):
        pad_len=15-(i%16)
        prefix=b'A'*pad_len
        target=oracle(prefix)[16*(i//16):16*(i//16)+16]
        for b in range(256):
            cand=oracle(prefix+known+bytes([b]))[16*(i//16):16*(i//16)+16]
            if cand==target:
                known+=bytes([b]); break
    return known
